DO $bloque$ BEGIN
  EXECUTE $vista$CREATE OR REPLACE VIEW "v_adjuntos" AS select "base_digital"."tipo" AS "tipo","base_digital"."id_ref01" AS "id_ref01","base_digital"."id_ref02" AS "id_ref02","base_digital"."id_ref03" AS "id_ref03","base_digital"."id_ref04" AS "id_ref04",count("base_digital"."id") AS "cant" from "base_digital" where ("base_digital"."estado")::text = 'ACTIVO' group by "base_digital"."tipo","base_digital"."id_ref01","base_digital"."id_ref02","base_digital"."id_ref03","base_digital"."id_ref04" order by "base_digital"."tipo" desc$vista$;
EXCEPTION WHEN others THEN
  RAISE WARNING 'No se pudo crear la vista v_adjuntos: %', SQLERRM;
END $bloque$;

