DO $bloque$ BEGIN
  EXECUTE $vista$CREATE OR REPLACE VIEW "v_data_cheques" AS select "p"."id" AS "id","p"."cliente" AS "cliente","r"."rut" AS "rut",concat("dc"."nombre","dc"."apellido") AS "nombre","p"."numdoc" AS "numdoc","p"."monto" AS "monto","p"."fec_venc" AS "fec_venc","p"."estado" AS "estado","p"."num_cheque" AS "num_cheque","p"."banco" AS "banco","tv"."glosa" AS "banco_name",'RECIBIDO' AS "tipo","p"."ref_id_doc" AS "ref_id_doc","r"."numdoc" AS "numdoc_F","r"."tipo_doc" AS "tipo_doc" from ((("docs_pagos" "p" cross join "docs_recibidos" "r") cross join "data_clientes" "dc") cross join "tablas_varias" "tv") where "p"."tipo_pago" = 2 and ("p"."tipo")::text = 'RECIBIDO' and ("p"."ref_id_doc")::text = ("r"."id")::text and ("p"."cliente")::text = ("dc"."codigo")::text and ("tv"."tipo")::text = 'BANCO' and ("p"."banco")::text = ("tv"."codigo")::text union select "p"."id" AS "id","p"."cliente" AS "cliente","e"."rut" AS "rut",concat("dc"."nombre","dc"."apellido") AS "nombre","p"."numdoc" AS "numdoc","p"."monto" AS "monto","p"."fec_venc" AS "fec_venc","p"."estado" AS "estado","p"."num_cheque" AS "num_cheque","p"."banco" AS "banco","tv"."glosa" AS "banco_name",'EMITIDO' AS "tipo","p"."ref_id_doc" AS "ref_id_doc","e"."numdoc" AS "numdoc_F","e"."tipo_doc" AS "tipo_doc" from ((("docs_pagos" "p" cross join "docs_emitidos" "e") cross join "data_clientes" "dc") cross join "tablas_varias" "tv") where "p"."tipo_pago" = 2 and ("p"."tipo")::text = 'EMITIDO' and ("p"."ref_id_doc")::text = ("e"."id")::text and ("p"."cliente")::text = ("dc"."codigo")::text and ("tv"."tipo")::text = 'BANCO' and ("p"."banco")::text = ("tv"."codigo")::text$vista$;
EXCEPTION WHEN others THEN
  RAISE WARNING 'No se pudo crear la vista v_data_cheques: %', SQLERRM;
END $bloque$;

DO $bloque$ BEGIN
  EXECUTE $vista$CREATE OR REPLACE VIEW "v_docs_pagos_cheques" AS select "docs_pagos"."id" AS "id","docs_pagos"."tipo" AS "tipo","docs_pagos"."ref_id_doc" AS "ref_id_doc","docs_pagos"."fecha_ing" AS "fecha_ing","docs_pagos"."cliente" AS "cliente","docs_pagos"."tipo_pago" AS "tipo_pago","docs_pagos"."numdoc" AS "numdoc","docs_pagos"."monto" AS "monto","docs_pagos"."saldo" AS "saldo","docs_pagos"."fecha_pago" AS "fecha_pago","docs_pagos"."fec_venc" AS "fec_venc","docs_pagos"."banco" AS "banco","docs_pagos"."num_cheque" AS "num_cheque","docs_pagos"."num_ctacte" AS "num_ctacte","docs_pagos"."estado" AS "estado","docs_pagos"."usuario" AS "usuario",case when "docs_pagos"."fec_venc" < current_date - interval (extract(isodow from (current_date)::date) - 1) day then 0 when "docs_pagos"."fec_venc" between current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 0 day and current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 6 day then 1 when "docs_pagos"."fec_venc" between current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 7 day and current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 13 day then 2 when "docs_pagos"."fec_venc" between current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 14 day and current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 20 day then 3 when "docs_pagos"."fec_venc" between current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 21 day and current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 27 day then 4 when "docs_pagos"."fec_venc" between current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 28 day and current_date - interval (extract(isodow from (current_date)::date) - 1) day + interval 34 day then 5 else 6 end AS "periodo_ag" from "docs_pagos" where "docs_pagos"."tipo_pago" = 2 and "docs_pagos"."fec_venc" >= '2025-01-01' and ("docs_pagos"."estado")::text = 'PENDIENTE'$vista$;
EXCEPTION WHEN others THEN
  RAISE WARNING 'No se pudo crear la vista v_docs_pagos_cheques: %', SQLERRM;
END $bloque$;

