DO $bloque$ BEGIN
  EXECUTE $vista$CREATE OR REPLACE VIEW "v_Fac_con_OC" AS select "e"."id" AS "id","e"."numdoc" AS "numdoc","e"."cliente" AS "cliente",cast("e"."fecha" as date) AS "fecha","e"."total" - coalesce("nc"."total",0) AS "total","e"."OC" AS "OC" from ("docs_recibidos" "e" left join "docs_recibidos" "nc" on("nc"."tipo_doc" = '61' and ("e"."cliente")::text = ("nc"."cliente")::text and ("e"."ref_num")::text = ("nc"."numdoc")::text and "e"."ref_tipo" = '61')) where "e"."tipo_doc" in ('33','34','39') and "e"."estado" not in ('ELIMINADO','ANULADO') and "e"."OC" > 0 and "e"."HES" <> 'RINGASTO' and cast("e"."fecha" as date) >= '2023-12-31' group by "e"."numdoc","e"."cliente" having "total" > 1000$vista$;
EXCEPTION WHEN others THEN
  RAISE WARNING 'No se pudo crear la vista v_Fac_con_OC: %', SQLERRM;
END $bloque$;

