DO $bloque$ BEGIN
  EXECUTE $vista$CREATE OR REPLACE VIEW "v_oc_fac_pag" AS select "e"."cliente" AS "oc_cliente","e"."numdoc" AS "oc_numdoc",substr("e"."fecha",1,10) AS "oc_fecha","e"."total" AS "oc_total",coalesce("r"."numdoc",0) AS "f_numdoc",coalesce(substr("r"."fecha",1,10),0) AS "f_fecha",coalesce("r"."total",0) AS "f_total",coalesce((select "vp"."total_pago" from "v_docs_pagos_fac" "vp" where ("vp"."cliente")::text = ("r"."cliente")::text and ("vp"."numdocF")::text = ("r"."numdoc")::text and ("vp"."id_pago")::text = ("pe"."id")::text),0) AS "f_pago",coalesce("r"."estado",0) AS "f_estado",coalesce("rnc"."numdoc",0) AS "nc_numdoc",coalesce("rnc"."total",0) AS "nc_total",coalesce("pe"."id",0) AS "p_numdoc",coalesce("pe"."fecha_pago",0) AS "p_fecha",coalesce("pe"."monto",0) AS "p_total",coalesce("pe"."saldo",0) AS "p_saldo",(CASE WHEN ("pe"."tipo")::text = 'EMITIDO' THEN 'OC1' ELSE (CASE WHEN ("pe"."tipo")::text = 'RECIBIDO' THEN 'FAC' ELSE NULL END) END) AS "p_tipo" from ((("docs_emitidos" "e" left join "docs_recibidos" "r" on(("r"."cliente")::text = ("e"."cliente")::text and ("r"."OC")::text = ("e"."numdoc")::text and "r"."tipo_doc" = '33' and "r"."HES" <> 'RINGASTO' and "r"."estado" not in ('RECHAZADO','DISTRIBUIDO'))) left join "docs_recibidos" "rnc" on(("r"."cliente")::text = ("rnc"."cliente")::text and ("r"."numdoc")::text = ("rnc"."ref_num")::text and "rnc"."tipo_doc" = '61')) left join "docs_pagos" "pe" on(("e"."cliente")::text = ("pe"."cliente")::text and (("e"."id")::text = ("pe"."ref_id_doc")::text or ("r"."id")::text = ("pe"."ref_id_doc")::text) and 0 <> (CASE WHEN ("r"."estado")::text = 'CERRADO' and 0 = (select case when "vp"."total_pago" = 0 then 1 else 0 end from "v_docs_pagos_fac" "vp" where ("vp"."cliente")::text = ("r"."cliente")::text and ("vp"."numdocF")::text = ("r"."numdoc")::text and ("vp"."id_pago")::text = ("pe"."id")::text) THEN 1 ELSE 0 END) and 0 <> (CASE WHEN ("r"."estado")::text = 'PENDIENTE' and 0 <> (select case when "vp"."total_pago" = 0 then 1 else 0 end from "v_docs_pagos_fac" "vp" where ("vp"."cliente")::text = ("r"."cliente")::text and ("vp"."numdocF")::text = ("r"."numdoc")::text and ("vp"."id_pago")::text = ("pe"."id")::text) THEN 0 ELSE 1 END))) where "e"."tipo_doc" = '801' and "e"."estado" not in ('ELIMINADO','ANULADO') and ("e"."fecha" > '2024-01-01' or "r"."fecha" > '2024-01-01') union select "r"."cliente" AS "oc_cliente",0 AS "oc_numdoc",0 AS "oc_fecha",0 AS "oc_total","r"."numdoc" AS "f_numdoc",substr("r"."fecha",1,10) AS "f_fecha","r"."total" AS "f_total",coalesce((select "vp"."total_pago" from "v_docs_pagos_fac" "vp" where ("vp"."cliente")::text = ("r"."cliente")::text and ("vp"."numdocF")::text = ("r"."numdoc")::text and ("vp"."id_pago")::text = ("pe"."id")::text),0) AS "f_pago","r"."estado" AS "f_estado",coalesce("rnc"."numdoc",0) AS "nc_numdoc",coalesce("rnc"."total",0) AS "nc_total",coalesce("pe"."id",0) AS "p_numdoc",coalesce("pe"."fecha_pago",0) AS "p_fecha",coalesce("pe"."monto",0) AS "p_total",coalesce("pe"."saldo",0) AS "p_saldo",(CASE WHEN ("pe"."tipo")::text = 'EMITIDO' THEN 'OC' ELSE (CASE WHEN ("pe"."tipo")::text = 'RECIBIDO' THEN 'FAC' ELSE NULL END) END) AS "p_tipo" from ((("docs_recibidos" "r" left join "docs_emitidos" "e" on(("r"."cliente")::text = ("e"."cliente")::text and ("r"."OC")::text = ("e"."numdoc")::text and "e"."tipo_doc" = '801')) left join "docs_recibidos" "rnc" on(("r"."cliente")::text = ("rnc"."cliente")::text and ("r"."numdoc")::text = ("rnc"."ref_num")::text and "rnc"."tipo_doc" = '61')) left join "docs_pagos" "pe" on(("r"."cliente")::text = ("pe"."cliente")::text and (("e"."id")::text = ("pe"."ref_id_doc")::text or ("r"."id")::text = ("pe"."ref_id_doc")::text))) where "r"."tipo_doc" = '33' and "r"."estado" not in ('RECHAZADO','DISTRIBUIDO') and "r"."HES" <> 'RINGASTO' and ("e"."fecha" > '2024-01-01' or "r"."fecha" > '2024-01-01') and "e"."id" is null or "e"."id" = 0 union select "r"."cliente" AS "oc_cliente","e"."numdoc" AS "oc_numdoc",substr("e"."fecha",1,10) AS "oc_fecha","e"."total" AS "oc_total","r"."numdoc" AS "f_numdoc",substr("r"."fecha",1,10) AS "f_fecha","r"."total" AS "f_total","r"."total" AS "f_pago","r"."estado" AS "f_estado","rnc"."numdoc" AS "nc_numdoc","rnc"."total" AS "nc_total",NULL AS "p_numdoc",NULL AS "p_fecha",NULL AS "p_total",NULL AS "p_saldo",'RINGASTO' AS "p_tipo" from (("docs_recibidos" "r" left join "docs_emitidos" "e" on(("r"."cliente")::text = ("e"."cliente")::text and ("r"."OC")::text = ("e"."numdoc")::text and "e"."tipo_doc" = '801')) left join "docs_recibidos" "rnc" on(("r"."cliente")::text = ("rnc"."cliente")::text and ("r"."numdoc")::text = ("rnc"."ref_num")::text and "rnc"."tipo_doc" = '61')) where "r"."tipo_doc" = '33' and "r"."estado" not in ('RECHAZADO','DISTRIBUIDO') and "r"."HES" = 'RINGASTO' and ("e"."fecha" > '2024-01-01' or "r"."fecha" > '2024-01-01')$vista$;
EXCEPTION WHEN others THEN
  RAISE WARNING 'No se pudo crear la vista v_oc_fac_pag: %', SQLERRM;
