LIMINADO','ANULADO') and "e"."fecha" > '2023-12-31' group by "e"."numdoc" union select "e"."id" AS "idOC","e"."numdoc" AS "numdoOC","e"."cliente" AS "cliente",cast("e"."fecha" as date) AS "fecha","e"."total" AS "montoOC","r"."numdoc" AS "factura","r"."total" AS "montoF","r"."estado" AS "estadoF","r"."id" AS "idFac" from ("docs_emitidos" "e" join "docs_recibidos" "r" on(("r"."cliente")::text = ("e"."cliente")::text and ("e"."numdoc")::text = ("r"."OC")::text and "r"."tipo_doc" in ('33','34','39') and ("r"."estado")::text = 'CERRADO' and "r"."HES" <> 'RINGASTO' and "r"."ref_tipo" <> '61')) where "e"."tipo_doc" = '801' and "e"."estado" not in ('ELIMINADO','ANULADO') and "e"."fecha" > '2023-12-31' group by "e"."numdoc") "t" left join "docs_pagos" "p" on(("t"."idOC")::text = ("p"."ref_id_doc")::text and ("p"."tipo")::text = 'EMITIDO' and ("t"."cliente")::text = ("p"."cliente")::text and ("p"."estado")::text = 'ACTIVO')) left join "docs_pagos" "q" on(("t"."idFac")::text = ("q"."ref_id_doc")::text and ("q"."tipo")::text = 'RECIBIDO' and ("t"."cliente")::text = ("q"."cliente")::text and ("q"."estado")::text = 'ACTIVO')) group by "t"."numdoOC" order by "numdoOC") "h" group by "h"."numdoOC" order by "h"."numdoOC"$vista$;
