f("b1"."id_responsable",0),nullif("b2"."id_responsable",0)))) left join "data_clientes" "rc" on("rc"."codigo" = coalesce(nullif("m"."id_responsable",0),nullif("b1"."id_responsable",0),nullif("b2"."id_responsable",0)))) where coalesce("m"."estado",'') <> 'ANULADO'$vista$;
